<script setup lang="ts">
import{onMounted,ref}from'vue';import{personsApi}from'../api';import{errorMessage}from'../api/http';import type{Person}from'../types';
const rows=ref<Person[]>([]),q=ref(''),editing=ref<Person>(),showEditor=ref(false),form=ref({name:'',remarks:''}),message=ref('');
async function load(){rows.value=await personsApi.search(q.value,true)}function open(p?:Person){showEditor.value=true;editing.value=p;form.value=p?{name:p.name,remarks:p.remarks||''}:{name:'',remarks:''}}
async function save(){try{if(editing.value)await personsApi.update(editing.value.id,form.value);else await personsApi.create(form.value);showEditor.value=false;editing.value=undefined;await load()}catch(e){message.value=errorMessage(e)}}async function toggle(p:Person){if(!confirm(`${p.active?'停用':'启用'}人员“${p.name}”？`))return;await personsApi.status(p.id,!p.active);await load()}onMounted(load);
</script>
<template><div class="page"><h1 class="page-title">人员管理</h1><p class="page-lead">登记时用于选择发送人和接收人。</p><div v-if="message" class="error-text">{{message}}</div><div class="row"><input class="input grow" v-model="q" placeholder="搜索姓名" @keyup.enter="load"/><button class="btn btn-secondary" @click="load">搜索</button></div><button class="btn btn-primary btn-block add" @click="open()">＋ 新增人员</button><section v-if="showEditor" class="card card-pad stack editor"><div class="field"><label class="required">姓名</label><input class="input" v-model.trim="form.name" placeholder="重名时可写：王伟（仓库）"/></div><div class="field"><label>备注</label><textarea class="textarea" v-model.trim="form.remarks"></textarea></div><div class="row"><button class="btn btn-primary grow" @click="save">保存人员</button><button class="btn btn-secondary" @click="showEditor=false">取消</button></div></section><div class="stack list"><article v-for="p in rows" :key="p.id" class="card card-pad row"><div class="grow"><strong>{{p.name}}</strong><div v-if="p.remarks" class="hint">{{p.remarks}}</div></div><span :class="['status',p.active?'ok':'neutral']">{{p.active?'启用':'停用'}}</span><button class="btn btn-ghost" @click="open(p)">编辑</button><button class="btn btn-secondary" @click="toggle(p)">{{p.active?'停用':'启用'}}</button></article></div></div></template>
<style scoped>.add{margin:12px 0}.editor{margin-bottom:14px}.list .row{flex-wrap:wrap}.list .btn{min-height:40px;padding:7px 11px}</style>
